 export const TASA_IVA = 0.13;

+// RF-002: la tasa sale de TASA_IVA (número entre 0 y 1); sin variable definida, 13 %. Un valor inválido es un error.
+export function tasaIva(env = process.env) {
+  const crudo = env.TASA_IVA;
+  if (crudo === undefined) return TASA_IVA;
+  const valor = Number(crudo);
+  if (!/^(\d+\.?\d*|\.\d+)$/.test(crudo) || valor > 1) throw new RangeError("TASA_IVA inválida: debe ser un número entre 0 y 1");
+  return valor;
+}
+
